CREATE TABLE IF NOT EXISTS migrations (version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE canon (id TEXT PRIMARY KEY, version INTEGER NOT NULL, document TEXT NOT NULL);
CREATE TABLE entities (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('person','location','organization')), name TEXT NOT NULL, document TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE storylines (id TEXT PRIMARY KEY, title TEXT NOT NULL, document TEXT NOT NULL, revision INTEGER NOT NULL DEFAULT 1);
CREATE TABLE events (id TEXT PRIMARY KEY, fingerprint TEXT NOT NULL UNIQUE, date TEXT NOT NULL, storyline_id TEXT NOT NULL REFERENCES storylines(id), status TEXT NOT NULL CHECK(status IN ('proposed','approved','rejected','published')), document TEXT NOT NULL, approved_at TEXT, published_at TEXT);
CREATE TABLE articles (id TEXT PRIMARY KEY, title TEXT NOT NULL, section TEXT NOT NULL, storyline_id TEXT NOT NULL REFERENCES storylines(id), status TEXT NOT NULL CHECK(status IN ('draft','approved','rejected','scheduled','published','retracted')), document TEXT NOT NULL, published_real TEXT, published_fiction TEXT, scheduled_at TEXT, revision INTEGER NOT NULL DEFAULT 1);
CREATE INDEX articles_published ON articles(status,published_fiction DESC,id);
CREATE TABLE article_events (article_id TEXT NOT NULL REFERENCES articles(id), event_id TEXT NOT NULL REFERENCES events(id), PRIMARY KEY(article_id,event_id));
CREATE TABLE article_entities (article_id TEXT NOT NULL REFERENCES articles(id), entity_id TEXT NOT NULL REFERENCES entities(id), PRIMARY KEY(article_id,entity_id));
CREATE INDEX entity_articles ON article_entities(entity_id,article_id);
CREATE TABLE fixtures (id TEXT PRIMARY KEY, event_id TEXT NOT NULL REFERENCES events(id), home TEXT NOT NULL, away TEXT NOT NULL, home_score INTEGER NOT NULL CHECK(home_score>=0), away_score INTEGER NOT NULL CHECK(away_score>=0), CHECK(home<>away));
CREATE TABLE audits (id INTEGER PRIMARY KEY AUTOINCREMENT, action TEXT NOT NULL, target TEXT NOT NULL, actor TEXT NOT NULL, created_at TEXT NOT NULL, before_json TEXT, after_json TEXT NOT NULL);
CREATE TRIGGER audit_no_update BEFORE UPDATE ON audits BEGIN SELECT RAISE(ABORT,'Audit records are append-only'); END;
CREATE TRIGGER audit_no_delete BEFORE DELETE ON audits BEGIN SELECT RAISE(ABORT,'Audit records are append-only'); END;
CREATE TABLE jobs (id TEXT PRIMARY KEY, status TEXT NOT NULL, created_at TEXT NOT NULL, attempts INTEGER NOT NULL DEFAULT 1, estimated_cents INTEGER NOT NULL DEFAULT 0, result TEXT, error TEXT);
CREATE INDEX jobs_daily ON jobs(created_at);
CREATE TABLE settings (id TEXT PRIMARY KEY, value TEXT NOT NULL);
CREATE TABLE users (id TEXT PRIMARY KEY, name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('reader','moderator')), verified INTEGER NOT NULL DEFAULT 0, suspended INTEGER NOT NULL DEFAULT 0);
CREATE TABLE threads (id TEXT PRIMARY KEY, article_id TEXT REFERENCES articles(id), author_id TEXT REFERENCES users(id), title TEXT NOT NULL, section TEXT NOT NULL, official INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, updated_at TEXT NOT NULL, hidden INTEGER NOT NULL DEFAULT 0, UNIQUE(article_id,official));
CREATE INDEX threads_activity ON threads(hidden,updated_at DESC,id);
CREATE TABLE comments (id TEXT PRIMARY KEY, thread_id TEXT NOT NULL REFERENCES threads(id), author_id TEXT NOT NULL REFERENCES users(id), parent_id TEXT REFERENCES comments(id), body TEXT NOT NULL, spoiler INTEGER NOT NULL DEFAULT 0, hidden INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL);
CREATE INDEX comments_thread ON comments(thread_id,hidden,created_at,id);
CREATE TABLE reactions (user_id TEXT NOT NULL REFERENCES users(id), comment_id TEXT NOT NULL REFERENCES comments(id), PRIMARY KEY(user_id,comment_id));
CREATE TABLE thread_follows (user_id TEXT NOT NULL REFERENCES users(id), thread_id TEXT NOT NULL REFERENCES threads(id), PRIMARY KEY(user_id,thread_id));
CREATE TABLE reports (id TEXT PRIMARY KEY, reporter_id TEXT NOT NULL REFERENCES users(id), comment_id TEXT NOT NULL REFERENCES comments(id), reason TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'open', created_at TEXT NOT NULL, UNIQUE(reporter_id,comment_id));
CREATE TABLE rate_limits (key TEXT PRIMARY KEY, started_at INTEGER NOT NULL, hits INTEGER NOT NULL);
